 IEnumerator Start(){folder=SportsEvidencePaths.Folder("KeepawayRegressionEvidence");background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);yield return Load(false);key=m.PreferenceKey;had=LWS.TruckSports.SportsPrefs.HasKey(key);saved=LWS.TruckSports.SportsPrefs.GetString(key);using(var stream=new FileStream(folder+"/preferences-before.json",FileMode.Create,FileAccess.Write,FileShare.Read)){using(var writer=new StreamWriter(stream,new System.Text.UTF8Encoding(false),1024,true)){writer.Write(JsonUtility.ToJson(new PreferenceBackup{had=had,saved=saved}));writer.Flush();}stream.Flush(true);}Application.logMessageReceived+=Error;
