 keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);yield return Load(false);
 for(int actor=0;actor<4;actor++){Configure(4);m.setup.players[actor].source=BowlingSource.AI;Check(m.StartMatch(),"isolated real AI pickup reproduction actor="+actor);foreach(var sheep in m.chaosField.sheep)sheep.Dormant();log.AppendLine("CONTACT_FIXTURE explosive sheep dormant; complete natural-hazard matches are checked separately. actor="+actor);for(int i=0;i<4;i++)m.trucks[i].Prepare(new Vector3(i%2==0?-27:27,.48f,i<2?-11:11),Quaternion.identity);m.trucks[actor].Prepare(new Vector3(0,.48f,-10),Quaternion.identity);Time.timeScale=3;float end=Time.realtimeSinceStartup+20;while(m.Carrier!=actor&&Time.realtimeSinceStartup<end)yield return null;Check(m.Carrier==actor,"AI physically collects loose ball actor="+actor);if(m.Carrier==actor){int thief=(actor+1)%4;for(int i=0;i<4;i++)m.setup.players[i].source=i==thief?BowlingSource.AI:BowlingSource.Keyboard;m.Gate();m.trucks[actor].Prepare(new Vector3(0,.48f,0),Quaternion.identity);m.trucks[thief].Prepare(new Vector3(0,.48f,-9),Quaternion.identity);yield return new WaitForSeconds(1);end=Time.realtimeSinceStartup+20;while(m.Carrier!=thief&&Time.realtimeSinceStartup<end)yield return null;log.AppendLine("CONTACT_FIXTURE actor="+actor+" thief="+thief+" carrier="+m.Carrier+" steals="+m.Steals+" pickups="+m.Pickups+" blasts="+m.Blasts);Check(m.Carrier==thief&&m.Steals>=1,"AI physically steals with genuine incoming body impact actor="+thief);if(m.Carrier==thief){int before=m.Steals;yield return new WaitForSeconds(.3f);Check(m.Steals==before,"one contact cannot repeatedly steal");int former=actor;end=Time.realtimeSinceStartup+5;while(!m.alive[former]&&Time.realtimeSinceStartup<end)yield return null;Check(m.alive[former],"exploded former carrier physically respawns");if(m.Carrier>=0){int carrier=m.Carrier;m.HazardBlast(m.trucks[carrier].body.position);Check(m.Carrier<0&&!m.ball.isKinematic&&m.ballShape.enabled,"hazard destruction drops exactly one loose ball");}}}m.SetupScreen();Time.timeScale=1;}
 yield return Load(true);Configure(4);for(int i=0;i<4;i++)m.setup.players[i].name="Opponent Name "+(i+1);Check(m.StartMatch()&&m.HumanViews==4,"four-cab steering and projected-label fixture starts");yield return null;yield return null;m.enabled=false;float[] inputs={-1,-.33f,.5f,1};for(int i=0;i<4;i++){m.cabViews[i].cabSteering.Bind(m.trucks[i]);m.trucks[i].TickDrive(new Vector2(inputs[i],0));}yield return new WaitForSecondsRealtime(2.5f);for(int i=0;i<4;i++){var c=m.cabViews[i].cabSteering;Check(c.Truck==m.trucks[i]&&Mathf.Abs(c.CurrentAngle-inputs[i]*450)<1,"independent actual Taxi wheel/NWH steering cab="+i+" angle="+c.CurrentAngle);}float angle=m.cabViews[0].cabSteering.CurrentAngle;m.Pause();yield return new WaitForSecondsRealtime(.15f);Check(m.cabViews[0].cabSteering.CurrentAngle==angle,"paused cab wheel does not drift");m.Resume();for(int i=0;i<4;i++)m.trucks[i].TickDrive(Vector2.zero);yield return new WaitForSecondsRealtime(2.3f);Check(m.cabViews.All(c=>Mathf.Abs(c.cabSteering.CurrentAngle)<.1f),"all stationary wheels naturally return to original neutral");m.enabled=true;
