 IEnumerator BlockedRecovery(){Configure(4);m.setup.players[0].source=BowlingSource.AI;Check(m.StartMatch(),"physical blocked-recovery fixture starts");Time.timeScale=1;m.trucks[0].Prepare(new Vector3(0,.48f,-12),Quaternion.identity);m.shield[0]=Time.time+30;var walls=new GameObject[3];for(int i=0;i<3;i++){walls[i]=new GameObject("Test-only solid recovery wall "+i);walls[i].transform.position=i==0?new Vector3(0,1,-9.7f):new Vector3(i==1?-1.9f:1.9f,1,-12);walls[i].AddComponent<BoxCollider>().size=i==0?new Vector3(4,2,.5f):new Vector3(.5f,2,4);}Physics.SyncTransforms();var backing=(float[])typeof(KeepawayMatch).GetField("backing",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(m);float deadline=Time.time+12,start=-1,end=-1;Vector3 first=default,last=default;bool continuous=true;while(Time.time<deadline){if(backing[0]>0&&start<0){start=Time.time;first=m.trucks[0].body.position;}if(start>=0){if(backing[0]>0&&m.trucks[0].command.y>=0)continuous=false;if(backing[0]<=0){end=Time.time;last=m.trucks[0].body.position;break;}}yield return new WaitForFixedUpdate();}Check(start>=0&&end-start>=1.02f&&continuous&&Vector3.Distance(first,last)>1,"actual solid-wall blockage executes uninterrupted bounded reverse · duration="+(end-start)+" displacement="+Vector3.Distance(first,last)+" (test protection isolates sheep blasts)");foreach(var wall in walls)Destroy(wall);m.SetupScreen();}
 void CaptureViews(int width,int height){var output=new Texture2D(width,height,TextureFormat.RGB24,false);var active=RenderTexture.active;foreach(var camera in m.cameras){var rect=camera.rect;int w=Mathf.RoundToInt(width*rect.width),h=Mathf.RoundToInt(height*rect.height);var rt=RenderTexture.GetTemporary(w,h,24);var old=camera.targetTexture;camera.targetTexture=rt;camera.rect=new Rect(0,0,1,1);camera.Render();RenderTexture.active=rt;output.ReadPixels(new Rect(0,0,w,h),Mathf.RoundToInt(width*rect.x),Mathf.RoundToInt(height*rect.y));camera.targetTexture=old;camera.rect=rect;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);}output.Apply();File.WriteAllBytes(folder+"/four-cameras-"+width+".png",output.EncodeToPNG());Destroy(output);RenderTexture.active=active;}
